/**
 * One row of a meta list: [label] („Erinnerung“) and its [value] („alle 2 Stunden“). [fileName] = the value is a file
 * name („export-2026-10-10.csv“): it breaks only after - . _ /, without a hyphen (D101 (6), sbFileName); an
 * identifier („1.4.0“) stays a plain value and never breaks inside (D80).
 */
@Immutable
data class SbMetaItem(val label: String, val value: String, val fileName: Boolean = false)

/**
 * Meta list (spec/02 §3.8): rows of at least 48 dp, the label in caption textMuted and the value in body with tabular
 * figures, columns 2 : 3 and centred, a 1 dp border hairline between rows. [labels] = sb-meta-list--labels (D80): a
 * label column of 160 dp times the text scale (the web's 10rem), the value in the rest, baseline-aligned, 12 dp above
 * and below, for long values (a place and how long it is kept, a path, a version line); once the value would keep
 * less than half the label column (large text on a phone), the label stands above the value. One TalkBack node per row.
 * The arrangement is one per list, never per row (§14.18); [stacked] not null sets it (true = every label above its
 * value), null measures it from the widest label and value of the whole list.
 */
@Composable
fun SbMetaList(items: List<SbMetaItem>, modifier: Modifier = Modifier, labels: Boolean = false, stacked: Boolean? = null) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val value = ty.body.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val measurer = rememberTextMeasurer()
    val widestLabel = remember(items, measurer) { items.maxOfOrNull { measurer.sbWidestWord(it.label, ty.caption) } ?: 0 }
    val widestValue = remember(items, measurer, value) { items.maxOfOrNull { measurer.sbWidestWord(it.shown, value) } ?: 0 }
    BoxWithConstraints(modifier.fillMaxWidth()) {
        // the web's minmax(0, 10rem): 160 dp that grow with the text (it holds text, §14.10; D99 (2))
        val column = (t.space.s16 * 2 + t.space.s8) * sbTextScale()
        // D99 (1): the plain 2 : 3 list also puts the label above the value once a word of either no longer fits
        // its column, so no word breaks
        val split = (constraints.maxWidth - with(LocalDensity.current) { t.space.s3.roundToPx() }) / 5f
        val onTop = stacked ?: if (labels) maxWidth - column - t.space.s3 < column / 2 else widestLabel > split * 2 || widestValue > split * 3
        Column(Modifier.fillMaxWidth()) {
            items.forEachIndexed { index, item ->
                val row = Modifier
                    .fillMaxWidth()
                    .heightIn(min = t.size.targetTouch)
                    .drawBehind {
                        if (index > 0) drawRect(c.border, Offset.Zero, Size(size.width, t.borderWidth.hairline.toPx()))
                    }
                    .semantics(mergeDescendants = true) { }
                    .padding(vertical = if (labels || onTop) t.space.s3 else t.space.s0)
                if (onTop) {
                    Column(row) {
                        SbWrapText(item.label, ty.caption, c.textMuted)
                        SbWrapText(item.shown, value, c.text)
                    }
                } else {
                    Row(row, horizontalArrangement = Arrangement.spacedBy(t.space.s3), verticalAlignment = Alignment.CenterVertically) {
                        if (labels) {
                            Text(item.label, style = ty.caption, color = c.textMuted, modifier = Modifier.width(column).alignByBaseline())
                            SbMetaValue(item, value, Modifier.weight(1f).alignByBaseline())
                        } else {
                            Text(item.label, style = ty.caption, color = c.textMuted, modifier = Modifier.weight(2f))
                            SbMetaValue(item, value, Modifier.weight(3f))
                        }
                    }
                }
            }
        }
    }
}

/** The value of a meta row as drawn: a file name marked (D101 (6)), anything else as it is. */
private val SbMetaItem.shown: AnnotatedString get() = if (fileName) sbFileName(value) else AnnotatedString(value)

/** A value beside its label: a plain Text (as before D101), a file name the wrappers' text that breaks after - . _ /. */
@Composable
private fun SbMetaValue(item: SbMetaItem, style: TextStyle, modifier: Modifier) {
    if (item.fileName) SbWrapText(item.shown, style, SebaroTheme.colors.text, modifier)
    else Text(item.value, style = style, color = SebaroTheme.colors.text, modifier = modifier)
}
